1 | /**
2 |  * dependencyInspector.ts
3 |  * ----------------------
4 |  * Allows selecting a piece of code or function/class in VS Code / IBM Bob IDE
5 |  * to inspect all its inbound callers, outbound callees, module dependencies,
6 |  * coupling classification, and safe-refactor risk tier.
7 |  */
8 | 
9 | import * as vscode from 'vscode';
10 | import * as path from 'path';
11 | import { EngineBridge } from './engineBridge';
12 | import { DependencyInspection } from './types';
13 | import { getOrCreatePanel, postMessage } from './webviewPanel';
14 | 
15 | export class DependencyInspector {
16 |     constructor(private readonly bridge: EngineBridge) {}
17 | 
18 |     /**
19 |      * Inspect dependencies of the currently selected piece of code or target symbol.
20 |      */
21 |     public async inspect(
22 |         context: vscode.ExtensionContext,
23 |         symbolArg?: string
24 |     ): Promise<void> {
25 |         let symbol = symbolArg?.trim();
26 | 
27 |         if (!symbol) {
28 |             const editor = vscode.window.activeTextEditor;
29 |             if (editor) {
30 |                 const selection = editor.selection;
31 |                 const selectedText = editor.document.getText(selection).trim();
32 | 
33 |                 // If user selected a specific symbol/identifier
34 |                 if (selectedText.length > 0 && selectedText.length < 120 && /^[\w$.]+$/.test(selectedText)) {
35 |                     symbol = selectedText;
36 |                 } else if (selectedText.length > 0) {
37 |                     // If user selected an expression or statement like `foo(bar)` or `def foo():`
38 |                     const match = /(?:def|class|function|func)?\s*([a-zA-Z_]\w*)/.exec(selectedText);
39 |                     if (match) {
40 |                         symbol = match[1];
41 |                     } else {
42 |                         symbol = selectedText.slice(0, 50);
43 |                     }
44 |                 } else {
45 |                     // Try word at current cursor position
46 |                     const wordRange = editor.document.getWordRangeAtPosition(selection.active, /[\w$]+/);
47 |                     if (wordRange) {
48 |                         symbol = editor.document.getText(wordRange).trim();
49 |                     }
50 |                 }
51 |             }
52 |         }
53 | 
54 |         if (!symbol) {
55 |             symbol = await vscode.window.showInputBox({
56 |                 title: 'IBM Bob: Inspect Code Dependencies',
57 |                 prompt: 'Enter the function, class, or symbol name to inspect callers and dependencies',
58 |                 placeHolder: 'e.g. dfs, extract_repo_ast, StorySynthesizer',
59 |             });
60 |         }
61 | 
62 |         if (!symbol || symbol.trim().length === 0) {
63 |             return;
64 |         }
65 | 
66 |         const targetSymbol = symbol.trim();
67 | 
68 |         await vscode.window.withProgress(
69 |             {
70 |                 location: vscode.ProgressLocation.Notification,
71 |                 title: `IBM Bob: Inspecting dependencies for "${targetSymbol}"…`,
72 |                 cancellable: true,
73 |             },
74 |             async (_progress, token) => {
75 |                 try {
76 |                     const inspection = await this.bridge.inspectDependencies(targetSymbol, token);
77 | 
78 |                     // 1. Reveal in Webview Panel
79 |                     const panel = getOrCreatePanel(context, (msg) => {
80 |                         if (msg.command === 'openFile' && msg.filePath) {
81 |                             const root = vscode.workspace.workspaceFolders?.[0]?.uri.fsPath ?? '';
82 |                             const absPath = path.isAbsolute(msg.filePath) ? msg.filePath : path.join(root, msg.filePath);
83 |                             void vscode.workspace.openTextDocument(vscode.Uri.file(absPath)).then((doc) => {
84 |                                 void vscode.window.showTextDocument(doc, {
85 |                                     selection: msg.line
86 |                                         ? new vscode.Range(
87 |                                               new vscode.Position(Math.max(0, msg.line - 1), 0),
88 |                                               new vscode.Position(Math.max(0, msg.line - 1), 0)
89 |                                           )
90 |                                         : undefined,
91 |                                 });
92 |                             });
93 |                         }
94 |                     });
95 | 
96 |                     postMessage({
97 |                         command: 'renderDependencies',
98 |                         payload: inspection,
99 |                     });
100 | 
101 |                     // 2. Offer QuickPick navigation menu for direct keyboard access
102 |                     void this.showQuickPickNavigator(inspection);
103 |                 } catch (err) {
104 |                     if (err instanceof vscode.CancellationError) { return; }
105 |                     const message = err instanceof Error ? err.message : String(err);
106 |                     void vscode.window.showErrorMessage(
107 |                         `IBM Bob: Dependency inspection failed for "${targetSymbol}".\n${message}`
108 |                     );
109 |                 }
110 |             }
111 |         );
112 |     }
113 | 
114 |     /**
115 |      * Interactive QuickPick menu allowing keyboard jump directly to callers or callees.
116 |      */
117 |     private async showQuickPickNavigator(inspection: DependencyInspection): Promise<void> {
118 |         interface NavItem extends vscode.QuickPickItem {
119 |             action: 'caller' | 'webview' | 'mindmap' | 'lock';
120 |             filePath?: string;
121 |             line?: number;
122 |         }
123 | 
124 |         const items: NavItem[] = [];
125 | 
126 |         // Header summary
127 |         items.push({
128 |             label: `$(symbol-method) Symbol: ${inspection.symbol_name}`,
129 |             description: `[${inspection.classification}] • Risk: ${inspection.risk_level}`,
130 |             detail: inspection.documented_usage,
131 |             action: 'webview',
132 |         });
133 | 
134 |         // Inbound Callers
135 |         if (inspection.callers.length > 0) {
136 |             items.push({
137 |                 label: `$(references) Inbound Callers (${inspection.callers.length} sites)`,
138 |                 kind: vscode.QuickPickItemKind.Separator,
139 |                 action: 'webview',
140 |             });
141 | 
142 |             for (const c of inspection.callers.slice(0, 15)) {
143 |                 items.push({
144 |                     label: `$(arrow-right) ${path.basename(c.caller_file)}:${c.line_number}`,
145 |                     description: `in ${c.enclosing_symbol}()`,
146 |                     detail: c.snippet || c.caller_file,
147 |                     action: 'caller',
148 |                     filePath: c.caller_file,
149 |                     line: c.line_number,
150 |                 });
151 |             }
152 |         } else {
153 |             items.push({
154 |                 label: `$(info) No Inbound Callers Detected (Decoupled Leaf)`,
155 |                 detail: 'Safe for immediate refactoring or extraction with zero ripple effect.',
156 |                 action: 'webview',
157 |             });
158 |         }
159 | 
160 |         // Outbound Callees
161 |         if (inspection.callees.length > 0) {
162 |             items.push({
163 |                 label: `$(call-outgoing) Outbound Dependencies (${inspection.callees.length} items)`,
164 |                 kind: vscode.QuickPickItemKind.Separator,
165 |                 action: 'webview',
166 |             });
167 | 
168 |             items.push({
169 |                 label: `$(package) Callees: ${inspection.callees.slice(0, 8).join(', ')}${inspection.callees.length > 8 ? '…' : ''}`,
170 |                 action: 'webview',
171 |             });
172 |         }
173 | 
174 |         // Actions
175 |         items.push({
176 |             label: `$(tools) Quick Actions`,
177 |             kind: vscode.QuickPickItemKind.Separator,
178 |             action: 'webview',
179 |         });
180 | 
181 |         items.push({
182 |             label: `$(graph) Open Interactive Dependency Webview`,
183 |             detail: 'View graphical callers and dependency DAG in Architecture Storyteller panel.',
184 |             action: 'webview',
185 |         });
186 | 
187 |         items.push({
188 |             label: `$(type-hierarchy-sub) View in Architecture Mindmap`,
189 |             detail: 'Open the full repository mindmap centered on this component.',
190 |             action: 'mindmap',
191 |         });
192 | 
193 |         const selected = await vscode.window.showQuickPick(items, {
194 |             title: `Dependency Navigator: ${inspection.symbol_name}`,
195 |             placeHolder: 'Select a caller to jump to code, or open visual inspector',
196 |             matchOnDescription: true,
197 |             matchOnDetail: true,
198 |         });
199 | 
200 |         if (!selected) { return; }
201 | 
202 |         if (selected.action === 'caller' && selected.filePath) {
203 |             const root = vscode.workspace.workspaceFolders?.[0]?.uri.fsPath ?? '';
204 |             const absPath = path.isAbsolute(selected.filePath) ? selected.filePath : path.join(root, selected.filePath);
205 |             const doc = await vscode.workspace.openTextDocument(vscode.Uri.file(absPath));
206 |             await vscode.window.showTextDocument(doc, {
207 |                 selection: selected.line
208 |                     ? new vscode.Range(
209 |                           new vscode.Position(Math.max(0, selected.line - 1), 0),
210 |                           new vscode.Position(Math.max(0, selected.line - 1), 0)
211 |                       )
212 |                     : undefined,
213 |             });
214 |         } else if (selected.action === 'mindmap') {
215 |             void vscode.commands.executeCommand('storyteller.mindmap', inspection.symbol_name);
216 |         }
217 |     }
218 | }
