1 | /**
2 |  * hoverProvider.ts
3 |  * ----------------
4 |  * Provides short documented usage and architectural context when a user hovers
5 |  * over a function, class, or symbol in VS Code / IBM Bob IDE for 1-2 seconds.
6 |  *
7 |  * Supported languages: Python, TypeScript, JavaScript, Go.
8 |  */
9 | 
10 | import * as vscode from 'vscode';
11 | import { EngineBridge } from './engineBridge';
12 | 
13 | const IGNORED_KEYWORDS = new Set([
14 |     'if', 'else', 'elif', 'while', 'for', 'in', 'of', 'do', 'switch', 'case', 'break',
15 |     'continue', 'return', 'yield', 'try', 'catch', 'finally', 'except', 'raise', 'throw',
16 |     'import', 'from', 'as', 'export', 'default', 'package', 'const', 'let', 'var',
17 |     'def', 'class', 'func', 'type', 'interface', 'struct', 'enum', 'true', 'false',
18 |     'null', 'undefined', 'nil', 'none', 'self', 'this', 'super', 'new', 'delete',
19 |     'async', 'await', 'public', 'private', 'protected', 'static', 'readonly',
20 | ]);
21 | 
22 | export class ArchitectureHoverProvider implements vscode.HoverProvider {
23 |     constructor(private readonly bridge: EngineBridge) {}
24 | 
25 |     public async provideHover(
26 |         document: vscode.TextDocument,
27 |         position: vscode.Position,
28 |         token: vscode.CancellationToken
29 |     ): Promise<vscode.Hover | null> {
30 |         // Check configuration toggle
31 |         const enabled = vscode.workspace
32 |             .getConfiguration('storyteller')
33 |             .get<boolean>('enableHover', true);
34 |         if (!enabled) { return null; }
35 | 
36 |         const wordRange = document.getWordRangeAtPosition(position, /[\w$]+/);
37 |         if (!wordRange) { return null; }
38 | 
39 |         const symbolName = document.getText(wordRange).trim();
40 |         if (!symbolName || symbolName.length < 2 || IGNORED_KEYWORDS.has(symbolName.toLowerCase())) {
41 |             return null;
42 |         }
43 | 
44 |         // Query the fast in-memory cache or background context bridge
45 |         const popup = await this.bridge.lookupSymbol(symbolName, token);
46 | 
47 |         // Fallback: If not indexed yet, check if there's local docstring/usage in current file
48 |         let documentedUsage = '';
49 |         let callersCount = popup ? popup.call_sites_count : 0;
50 |         let complexity = popup ? popup.complexity : 1;
51 |         let author = popup?.backstory?.author || '';
52 |         let whyWritten = popup?.backstory?.why_it_was_written || '';
53 |         let sourceRef = popup?.backstory?.commit_sha ? `commit ${popup.backstory.commit_sha.slice(0, 7)}` : '';
54 | 
55 |         if (popup?.definition_code) {
56 |             const docMatch = /"""([\s\S]*?)"""|\/\*\*([\s\S]*?)\*\//.exec(popup.definition_code);
57 |             if (docMatch) {
58 |                 documentedUsage = (docMatch[1] || docMatch[2] || '')
59 |                     .trim()
60 |                     .split('\n')[0]
61 |                     .replace(/^[\s*]+/, '')
62 |                     .trim();
63 |             }
64 |         }
65 | 
66 |         if (!documentedUsage && whyWritten) {
67 |             documentedUsage = whyWritten;
68 |         }
69 | 
70 |         // If neither popup nor local doc was found, don't clutter normal editing
71 |         if (!popup && !documentedUsage) {
72 |             return null;
73 |         }
74 | 
75 |         if (!documentedUsage) {
76 |             documentedUsage = `Documented component referenced across ${callersCount} call site(s).`;
77 |         }
78 | 
79 |         // Classification badge
80 |         let classification = 'Cluster A (Independent Leaf)';
81 |         if (popup?.unusual_flags && popup.unusual_flags.length > 0) {
82 |             classification = 'Cluster C (Dynamic / Reflection)';
83 |         } else if (callersCount > 4 || complexity > 8) {
84 |             classification = 'Cluster B (Cross-Module Seam)';
85 |         }
86 | 
87 |         const md = new vscode.MarkdownString();
88 |         md.isTrusted = true;
89 |         md.supportHtml = true;
90 | 
91 |         md.appendMarkdown(`### 🏛️ **IBM Bob Architecture** • \`${symbolName}\`\n\n`);
92 |         md.appendMarkdown(`**Documented Usage:**\n`);
93 |         md.appendMarkdown(`> *${documentedUsage}*\n\n`);
94 | 
95 |         md.appendMarkdown(`---\n`);
96 |         md.appendMarkdown(`📊 **Metrics:** \`${callersCount} Callers\` &bull; \`Complexity: ${complexity}\` &bull; \`${classification}\`\n\n`);
97 | 
98 |         if (author || whyWritten) {
99 |             md.appendMarkdown(`📜 **Archival Backstory:**\n`);
100 |             if (whyWritten && whyWritten !== documentedUsage) {
101 |                 md.appendMarkdown(`- *${whyWritten}*\n`);
102 |             }
103 |             if (author) {
104 |                 md.appendMarkdown(`- Authored by **@${author}** ${sourceRef ? `(${sourceRef})` : ''}\n`);
105 |             }
106 |             md.appendMarkdown(`\n`);
107 |         }
108 | 
109 |         const encodedArg = encodeURIComponent(JSON.stringify(symbolName));
110 |         md.appendMarkdown(`---\n`);
111 |         md.appendMarkdown(
112 |             `[🔍 Inspect Dependencies](command:storyteller.inspectDependencies?${encodedArg} "Inspect callers, callees, and dependency tree") &nbsp;|&nbsp; ` +
113 |             `[🗺️ Mindmap](command:storyteller.mindmap?${encodedArg} "Open in interactive architecture mindmap") &nbsp;|&nbsp; ` +
114 |             `[📖 Context Story](command:storyteller.context?${encodedArg} "View full git archival backstory") &nbsp;|&nbsp; ` +
115 |             `[🤖 Ask Bob AI](command:storyteller.askBobAI?${encodedArg} "Ask IBM Bob AI about this component")`
116 |         );
117 | 
118 |         return new vscode.Hover(md, wordRange);
119 |     }
120 | }
121 | 
122 | /**
123 |  * Register hover provider across all polyglot languages.
124 |  */
125 | export function registerArchitectureHoverProvider(
126 |     context: vscode.ExtensionContext,
127 |     bridge: EngineBridge
128 | ): void {
129 |     const selector: vscode.DocumentSelector = [
130 |         { scheme: 'file', language: 'python' },
131 |         { scheme: 'file', language: 'typescript' },
132 |         { scheme: 'file', language: 'javascript' },
133 |         { scheme: 'file', language: 'typescriptreact' },
134 |         { scheme: 'file', language: 'javascriptreact' },
135 |         { scheme: 'file', language: 'go' },
136 |     ];
137 | 
138 |     const provider = new ArchitectureHoverProvider(bridge);
139 |     context.subscriptions.push(
140 |         vscode.languages.registerHoverProvider(selector, provider)
141 |     );
142 | }
