1 | /**
2 |  * extension.ts
3 |  * ------------
4 |  * VS Code Extension entry point for Architecture Storyteller & Archival Context.
5 |  *
6 |  * Registered commands
7 |  * -------------------
8 |  *  storyteller.mindmap       – Full storyboard + interactive Mermaid mindmap
9 |  *  storyteller.context       – Archival context inspector for a specific symbol
10 |  *  storyteller.pdf           – Export PDF via tools/storyteller-engine/cli.py
11 |  *  storyteller.exportDossier – Full publication dossier via generate_dossier.py
12 |  *
13 |  * Lifecycle
14 |  * ---------
15 |  *  activate()   – called once when any activation event fires
16 |  *  deactivate() – called on extension unload (cleanup)
17 |  */
18 | 
19 | import * as vscode from 'vscode';
20 | import * as path from 'path';
21 | 
22 | import { registerTerminalSlashWatcher }    from './terminalWatcher';
23 | import { promptUserForAnalysisScope }      from './depthModal';
24 | import { EngineBridge }                    from './engineBridge';
25 | import {
26 |     getOrCreatePanel,
27 |     disposePanel,
28 |     postMessage,
29 |     WebviewInboundMessage,
30 | } from './webviewPanel';
31 | import { AnalysisScopeOptions }            from './types';
32 | import { registerArchitectureHoverProvider } from './hoverProvider';
33 | import { DependencyInspector }               from './dependencyInspector';
34 | 
35 | // ---------------------------------------------------------------------------
36 | // Module-level singletons
37 | // ---------------------------------------------------------------------------
38 | 
39 | let _bridge: EngineBridge | undefined;
40 | 
41 | function getBridge(): EngineBridge {
42 |     if (!_bridge) {
43 |         _bridge = new EngineBridge();
44 |     }
45 |     return _bridge;
46 | }
47 | 
48 | // ---------------------------------------------------------------------------
49 | // Shared webview message handler
50 | // ---------------------------------------------------------------------------
51 | 
52 | let _lastStoryboard: import('./types').ArchitectureStoryboard | undefined;
53 | 
54 | function handleWebviewMessage(
55 |     context: vscode.ExtensionContext,
56 |     msg: WebviewInboundMessage
57 | ): void {
58 |     switch (msg.command) {
59 |         case 'ready':
60 |             if (_lastStoryboard) {
61 |                 postMessage({ command: 'render', payload: _lastStoryboard });
62 |             }
63 |             break;
64 | 
65 |         case 'exportPdf':
66 |             void vscode.commands.executeCommand('storyteller.pdf');
67 |             break;
68 | 
69 |         case 'openFile': {
70 |             if (!msg.filePath) { break; }
71 |             const bridge = getBridge();
72 |             const root   = (vscode.workspace.workspaceFolders?.[0]?.uri.fsPath) ?? '';
73 |             const absPath = path.isAbsolute(msg.filePath)
74 |                 ? msg.filePath
75 |                 : path.join(root, msg.filePath);
76 |             const fileUri = vscode.Uri.file(absPath);
77 |             void vscode.workspace.openTextDocument(fileUri).then((doc) => {
78 |                 void vscode.window.showTextDocument(doc, {
79 |                     preview: true,
80 |                     selection: msg.line
81 |                         ? new vscode.Range(
82 |                             new vscode.Position(Math.max(0, (msg.line ?? 1) - 1), 0),
83 |                             new vscode.Position(Math.max(0, (msg.line ?? 1) - 1), 0)
84 |                           )
85 |                         : undefined,
86 |                 });
87 |             });
88 |             break;
89 |         }
90 | 
91 |         case 'openContext': {
92 |             if (msg.symbolName) {
93 |                 void vscode.commands.executeCommand('storyteller.context', msg.symbolName);
94 |             }
95 |             break;
96 |         }
97 | 
98 |         case 'askBobAI': {
99 |             if (msg.symbolName) {
100 |                 void vscode.commands.executeCommand('storyteller.askBobAI', msg.symbolName);
101 |             }
102 |             break;
103 |         }
104 |     }
105 | }
106 | 
107 | // ---------------------------------------------------------------------------
108 | // Command: storyteller.mindmap
109 | // ---------------------------------------------------------------------------
110 | 
111 | async function commandMindmap(
112 |     context: vscode.ExtensionContext,
113 |     initialSymbol?: string
114 | ): Promise<void> {
115 |     const scope = await promptUserForAnalysisScope(initialSymbol);
116 |     if (!scope) { return; }
117 | 
118 |     // Ensure artifact is mindmap when called from this command
119 |     const options: AnalysisScopeOptions = { ...scope, artifact: 'mindmap' };
120 | 
121 |     const panel = getOrCreatePanel(context, (msg) => handleWebviewMessage(context, msg));
122 |     postMessage({ command: 'loading', message: 'Analysing repository architecture…' });
123 | 
124 |     const bridge = getBridge();
125 | 
126 |     await vscode.window.withProgress(
127 |         {
128 |             location: vscode.ProgressLocation.Notification,
129 |             title: 'Architecture Storyteller',
130 |             cancellable: true,
131 |         },
132 |         async (_progress, token) => {
133 |             try {
134 |                 const storyboard = await bridge.executeMindmap(options, token);
135 |                 _lastStoryboard = storyboard;
136 |                 postMessage({ command: 'render', payload: storyboard });
137 |             } catch (err) {
138 |                 if (err instanceof vscode.CancellationError) {
139 |                     postMessage({ command: 'error', message: 'Analysis cancelled.' });
140 |                     return;
141 |                 }
142 |                 const message = err instanceof Error ? err.message : String(err);
143 |                 postMessage({ command: 'error', message });
144 |                 void vscode.window.showErrorMessage(
145 |                     `Architecture Storyteller: Mindmap failed.\n${message}`
146 |                 );
147 |             }
148 |         }
149 |     );
150 | }
