156 | async function commandContext(
157 |     context: vscode.ExtensionContext,
158 |     symbolArg?: string
159 | ): Promise<void> {
160 |     // Resolve initial symbol: argument > editor selection > modal input
161 |     let initialSymbol = symbolArg;
162 | 
163 |     if (!initialSymbol) {
164 |         const editor = vscode.window.activeTextEditor;
165 |         if (editor) {
166 |             const sel = editor.document.getText(editor.selection).trim();
167 |             if (sel.length > 0 && sel.length < 120 && /^[\w.]+$/.test(sel)) {
168 |                 initialSymbol = sel;
169 |             }
170 |         }
171 |     }
172 | 
173 |     const scope = await promptUserForAnalysisScope(initialSymbol);
174 |     if (!scope) { return; }
175 | 
176 |     const options: AnalysisScopeOptions = { ...scope, artifact: 'context' };
177 | 
178 |     if (!options.symbol) {
179 |         void vscode.window.showWarningMessage(
180 |             'Architecture Storyteller: No symbol specified for context analysis.'
181 |         );
182 |         return;
183 |     }
184 | 
185 |     const panel = getOrCreatePanel(context, (msg) => handleWebviewMessage(context, msg));
186 |     postMessage({
187 |         command: 'loading',
188 |         message: `Fetching archival context for "${options.symbol}"…`,
189 |     });
190 | 
191 |     const bridge = getBridge();
192 | 
193 |     await vscode.window.withProgress(
194 |         {
195 |             location: vscode.ProgressLocation.Notification,
196 |             title: `Context: ${options.symbol}`,
197 |             cancellable: true,
198 |         },
199 |         async (_progress, token) => {
200 |             try {
201 |                 const storyboard = await bridge.executeContext(options, token);
202 |                 _lastStoryboard = storyboard;
203 |                 postMessage({ command: 'render', payload: storyboard });
204 |             } catch (err) {
205 |                 if (err instanceof vscode.CancellationError) {
206 |                     postMessage({ command: 'error', message: 'Context lookup cancelled.' });
207 |                     return;
208 |                 }
209 |                 const message = err instanceof Error ? err.message : String(err);
210 |                 postMessage({ command: 'error', message });
211 |                 void vscode.window.showErrorMessage(
212 |                     `Architecture Storyteller: Context failed.\n${message}`
213 |                 );
214 |             }
215 |         }
216 |     );
217 | }
