118 |     private spawnProcess(
119 |         executable: string,
120 |         args: string[],
121 |         cwd: string,
122 |         token?: vscode.CancellationToken
123 |     ): Promise<SpawnResult> {
124 |         return new Promise((resolve, reject) => {
125 |             const spawnOpts: SpawnOptionsWithoutStdio = {
126 |                 cwd,
127 |                 env: { ...process.env, PYTHONUNBUFFERED: '1' },
128 |                 shell: false,
129 |             };
130 | 
131 |             const child = spawn(executable, args, spawnOpts);
132 | 
133 |             const stdoutChunks: Buffer[] = [];
134 |             const stderrChunks: Buffer[] = [];
135 | 
136 |             child.stdout.on('data', (chunk: Buffer) => stdoutChunks.push(chunk));
137 |             child.stderr.on('data', (chunk: Buffer) => stderrChunks.push(chunk));
138 | 
139 |             child.on('error', (err: Error) => {
140 |                 reject(
141 |                     new Error(
142 |                         `Failed to start process "${executable}": ${err.message}. ` +
143 |                         `Verify storyteller.pythonPath in settings.`
144 |                     )
145 |                 );
146 |             });
147 | 
148 |             child.on('close', (code: number | null) => {
149 |                 resolve({
150 |                     stdout: Buffer.concat(stdoutChunks).toString('utf8'),
151 |                     stderr: Buffer.concat(stderrChunks).toString('utf8'),
152 |                     exitCode: code ?? -1,
153 |                 });
154 |             });
155 | 
156 |             // Support cancellation
157 |             if (token) {
158 |                 token.onCancellationRequested(() => {
159 |                     child.kill('SIGTERM');
160 |                     reject(new vscode.CancellationError());
161 |                 });
162 |             }
163 |         });
